input.script:
users = list_users()
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
slots = [
  { m: 540, t: "09:00", e: "10:00" },
  { m: 570, t: "09:30", e: "10:30" },
  { m: 600, t: "10:00", e: "11:00" },
  { m: 630, t: "10:30", e: "11:30" },
  { m: 660, t: "11:00", e: "12:00" },
  { m: 690, t: "11:30", e: "12:30" },
  { m: 720, t: "12:00", e: "13:00" },
  { m: 750, t: "12:30", e: "13:30" },
  { m: 780, t: "13:00", e: "14:00" },
  { m: 810, t: "13:30", e: "14:30" },
  { m: 840, t: "14:00", e: "15:00" },
  { m: 870, t: "14:30", e: "15:30" },
  { m: 900, t: "15:00", e: "16:00" },
  { m: 930, t: "15:30", e: "16:30" },
  { m: 960, t: "16:00", e: "17:00" }
]
days = for d in dates {
    avails = for u in users {
        a = boundary retry 2 {
            return get_availability({ user_id: u.id, date: d })
        } catch err {
            return fail("AVAIL_FAILED", err.code + ": " + err.message)
        }
        return a.busy if a.busy != null else []
    }
    busy = fold acc = [] for bl in avails {
        return acc + bl
    }
    return { date: d, busy: busy }
}
per_day = for day in days {
    free = for slot in slots {
        ok = fold acc = true for iv in day.busy {
            st = iv.start if iv.start != null else "00:00"
            en = iv.end if iv.end != null else "24:00"
            bs = number.parse(text.slice(st, 0, 2)) * 60 + number.parse(text.slice(st, 3, 5))
            be = number.parse(text.slice(en, 0, 2)) * 60 + number.parse(text.slice(en, 3, 5))
            return acc and not (bs < slot.m + 60 and be > slot.m)
        }
        skip if not ok
        return slot
    }
    return { date: day.date, free: free }
}
chosen = fold acc = null for pd in per_day {
    return acc if acc != null else ({ date: pd.date, slot: pd.free[0] } if pd.free != [] else null)
}
assert(chosen != null, "no suitable slot found in the week")
start_iso = chosen.date + "T" + chosen.slot.t + ":00Z"
end_iso = chosen.date + "T" + chosen.slot.e + ":00Z"
res = submit_result({ answer: { start: start_iso, end: end_iso } })
return { recorded: res.recorded, start: start_iso, end: end_iso }

